#include <cctype>
#include <sstream>
#include <string>
#include <vector>

std::vector<std::string> exportedNames(const std::string& dumpbinOutput)
{
    std::vector<std::string> names;
    std::istringstream lines{ dumpbinOutput };
    std::string line;
    bool inTable{ false };
    bool seenRow{ false };
    while (std::getline(lines, line))
    {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (!inTable)
        {
            if (line.find("ordinal") != std::string::npos && line.find("hint") != std::string::npos && line.find("RVA") != std::string::npos && line.find("name") != std::string::npos) inTable = true;
            continue;
        }
        std::istringstream words{ line };
        std::vector<std::string> w;
        for (std::string word; words >> word;) w.push_back(word);
        if (w.empty()) { if (seenRow) break; continue; }
        if (w[0] == "Summary") break;
        if (!std::isdigit(static_cast<unsigned char>(w[0][0]))) continue;
        seenRow = true;
        // ordinal [hint] RVA name: the RVA is the 8-character word
        std::size_t at{ 1 };
        if (at < w.size() && w[at].size() != 8) ++at;     // skip the hint
        if (at + 1 >= w.size()) continue;
        const std::string& name{ w[at + 1] };
        names.push_back(name == "[NONAME]" ? "#" + w[0] : name);
    }
    return names;
}
